tId, @userId,  SYSDATETIMEOFFSET(), @userId,      SYSDATETIMEOFFSET(), 1, @unitId,      @routeId,      2,      @scheduleId,    0,    1,      'Cancelled',    @medId)       ,(@hateOasPtId, @userId,  SYSDATETIMEOFFSET(), @userId,      SYSDATETIMEOFFSET(), 1, @unitId,      @routeId,      2,      @scheduleId,    0,    1,      'Deleted',    @medId)       ,(@hateOasPtId, @userId,  SYSDATETIMEOFFSET(), @userId,      SYSDATETIMEOFFSET(), 1, @unitId,      @routeId,      2,      @scheduleId,    1,    0,      'Pending',    @medId)       ,(@hateOasPtId, @userId,  SYSDATETIMEOFFSET(), @userId,      SYSDATETIMEOFFSET(), 1, @unitId,      @routeId,      2,      @scheduleId,    1,    1,      'Pending',    @medId)       ,(@hateOasPtId, @userId,  SYSDATETIMEOFFSET(), @userId,      SYSDATETIMEOFFSET(), 1, @unitId,      @routeId,      2,      @scheduleId,    1,    0,      'OnGoing',    @medId)       ,(@hateOasPtId, @userId,  SYSDATETIMEOFFSET(), @userId,      SYSDATETIMEOFFSET(), 1, @unitId,      @routeId,      2,      @scheduleId,    1,    1,      'OnGoing',    @medId)       ,(@hateOasPtId, @userId,  SYSDATETIMEOFFSET(), @userId,      SYSDATETIMEOFFSET(), 1, @unitId,      @routeId,      2,      @scheduleId,    1,    1,      'OnHold',    @medId)       ,(@hateOasPtId, @userId,  SYSDATETIMEOFFSET(), @userId,      SYSDATETIMEOFFSET(), 1, @unitId,      @routeId,      2,      @scheduleId,    1,    1,      'PendingDiscontinue',    @medId)       ,(@hateOasPtId, @userId,  SYSDATETIMEOFFSET(), @userId,      SYSDATETIMEOFFSET(), 1, @unitId,      @routeId,      2,      @scheduleId,    1,    1,      'Discontinued',    @medId)       ,(@hateOasPtId, @userId,  SYSDATETIMEOFFSET(), @userId,      SYSDATETIMEOFFSET(), 1, @unitId,      @routeId,      2,      @scheduleId,    1,    1,      'Completed',    @medId)       ,(@hateOasPtId, @userId,  SYSDATETIMEOFFSET(), @userId,      SYSDATETIMEOFFSET(), 1, @unitId,      @routeId,      2,      @scheduleId,    1,    1,      'Cancelled',    @medId)       ,(@hateOasPtId, @userId,  SYSDATETIMEOFFSET(), @userId,      SYSDATETIMEOFFSET(), 1, @unitId,      @routeId,      2,      @scheduleId,    1,    1,      'Deleted',    @medId)   /**/   DECLARE  @OrderId bigint = (SELECT id FROM patient_orders WHERE patient_id = @hateOasPtId       AND order_status = 'OnGoing'       AND prn = 0       AND point_in_time = 1),       @cancelOrderId bigint = (SELECT id FROM patient_orders WHERE patient_id = @hateOasPtId       AND order_status = 'Pending'       AND prn = 0       AND point_in_time = 1),       @date DATETIMEOFFSET = TODATETIMEOFFSET(CONVERT(Date, GETDATE()), DATEPART(tz, DATEADD(hour, 1, SYSDATETIMEOFFSET()))),       @hour int = DATEPART(hour, GETDATE());   SET @hour = CASE WHEN @hour > 20 THEN 20 ELSE @hour END;   /**/   WITH src AS (     SELECT  *     FROM ( VALUES       (@cancelOrderId, 1, 0, 0,  DATEADD(hour, @hour, DATEADD(mi, 30, @date)))       ,(@cancelOrderId, 1, 0, 0,  DATEADD(hour, @hour + 1, DATEADD(mi, 30, @date)))       ,(@cancelOrderId, 1, 0, 0,  DATEADD(hour, @hour + 2, DATEADD(mi, 30, @date)))       ,(@cancelOrderId, 1, 0, 0,  DATEADD(hour, @hour + 3, DATEADD(mi, 30, @date)))       ,(@orderId, 1, 0, 0,  DATEADD(hour, @hour, DATEADD(mi, 30, @date)))       ,(@orderId, 1, 0, 0,  DATEADD(hour, @hour + 1, DATEADD(mi, 30, @date)))       ,(@orderId, 1, 0, 0,  DATEADD(hour, @hour + 2, DATEADD(mi, 30, @date)))       ,(@orderId, 1, 0, 0,  DATEADD(hour, @hour + 3, DATEADD(mi, 30, @date)))     ) t (patient_order_id, point_in_time, on_hold, missed_dose, scheduled)   )   INSERT  order_administrations       (patient_order_id, point_in_time, on_hold, missed_dose, administration_scheduled_datetime)   SELECT  patient_order_id,  point_in_time, on_hold, missed_dose, scheduled   FROM src;   /**/   DECLARE  @AdminId BIGINT = SCOPE_IDENTITY();   /**/   DECLARE @ackUserId int = (SELECT id FROM dbo.users where site_id = <<SiteId>> and first_name = 'Antonio' AND last_name = 'Biliardis')   DECLARE @stopUserId int = (SELECT id FROM dbo.users where site_id = <<SiteId>> and first_name = 'John' AND last_name = 'Humanski')   /**/   UPDATE order_administrations   SET    administering_user_id = @userId       ,acknowledge_user_id = @ackUserId       ,stop_user_id = @stopUserId   WHERE  id = @AdminId;   /**/   WITH src AS (     SELECT * FROM (VALUES       (@orderId, NULL,  TODATETIMEOFFSET (DATEADD(hour, 1, GETDATE()), '-05:00'), @userId,  SYSDATETIMEOFFSET(), 5)       ,(@orderId, NULL,  TODATETIMEOFFSET (DATEADD(hour, 2, GETDATE()), '-05:00'), @userId,  SYSDATETIMEOFFSET(), 5)       ,(@orderId, NULL,  TODATETIMEOFFSET (DATEADD(hour, 3, GETDATE()), '-05:00'), @userId,  SYSDATETIMEOFFSET(), 11)       ,(@orderId, NULL,  TODATETIMEOFFSET (DATEADD(hour, 4, GETDATE()), '-05:00'), @userId,  SYSDATETIMEOFFSET(), 4)       ,(@orderId, @AdminId - 2,  TODATETIMEOFFSET (DATEADD(hour, 1, GETDATE()), '-05:00'), @userId,  SYSDATETIMEOFFSET(), 5)       ,(@orderId, @AdminId - 2,  TODATETIMEOFFSET (DATEADD(hour, 2, GETDATE()), '-05:00'), @userId,  SYSDATETIMEOFFSET(), 5)       ,(@orderId, @AdminId - 2,  TODATETIMEOFFSET (DATEADD(hour, 3, GETDATE()), '-05:00'), @userId,  SYSDATETIMEOFFSET(), 9)       ,(@orderId, @AdminId - 2,  TODATETIMEOFFSET (DATEADD(hour, 4, GETDATE()), '-05:00'), @userId,  SYSDATETIMEOFFSET(), 10)       ,(@orderId, @AdminId - 1,  TODATETIMEOFFSET (DATEADD(hour, 1, GETDATE()), '-05:00'), @userId,  SYSDATETIMEOFFSET(), 9)       ,(@orderId, @AdminId - 1,  TODATETIMEOFFSET (DATEADD(hour, 2, GETDATE()), '-05:00'), @userId,  SYSDATETIMEOFFSET(), 10)       ,(@orderId, @AdminId,  TODATETIMEOFFSET (DATEADD(hour, 1, GETDATE()), '-05:00'), @userId,  SYSDATETIMEOFFSET(), 5)       ,(@orderId, @AdminId,  TODATETIMEOFFSET (DATEADD(hour, 2, GETDATE()), '-05:00'), @userId,  SYSDATETIMEOFFSET(), 5)       ,(@orderId, @AdminId,  TODATETIMEOFFSET (DATEADD(hour, 2, GETDATE()), '-05:00'), @userId,  SYSDATETIMEOFFSET(), 5)       /* 4 events which need to be cleared before the order can be cancelled - 2 specific to admins, one to the order only*/       ,(@cancelOrderId, @AdminId - 4,  TODATETIMEOFFSET (DATEADD(hour, 2, GETDATE()), '-05:00'), @userId,  SYSDATETIMEOFFSET(), 5)       ,(@cancelOrderId, @AdminId -6,  TODATETIMEOFFSET (DATEADD(hour, 2, GETDATE()), '-05:00'), @userId,  SYSDATETIMEOFFSET(), 5)       ,(@cancelOrderId, NULL,  TODATETIMEOFFSET (DATEADD(hour, 2, GETDATE()), '-05:00'), @userId,  SYSDATETIMEOFFSET(), 5)     ) t (patient_order_id, order_administration_id, event_datetime, add_user_id, add_datetime, action_id)   )   INSERT  dbo.order_events       (patient_order_id, order_administration_id, event_datetime, add_user_id, add_datetime, action_id)   SELECT  patient_order_id, order_administration_id, event_datetime, add_user_id, add_datetime, action_id   FROM  src;   /**/   DECLARE  @adminEventId bigint = (SELECT id FROM order_events WHERE patient_order_id = @cancelOrderId and order_administration_id = @AdminId - 4)       ,@orderEventId bigint = (SELECT id FROM order_events WHERE patient_order_id = @cancelOrderId and order_administration_id IS NULL)       ,@promptId int = (SELECT id FROM prompts where prompt = 'Change in medication plan');   /**/   WITH src AS (     SELECT * FROM (VALUES       (@adminEventId, @promptId, 'Change in medication plan', 'true'),       (@orderEventId, @promptId, 'Change in medication plan', 'true')     ) t (order_event_id, prompt_id, prompt_text, entered_text)   )   INSERT  dbo.order_event_details   SELECT * FROM src;   /**/   /**/   SELECT CONCAT(       'actionEventPatientId|', @hateOasPtId,       '~actionEventOrderid|', @orderId,       '~actionEventAdminTopId|', @AdminId,       '~actionEventUserId|', @userId,       '~actionEventAckUserId|', @ackUserId,       '~actionEventStopUserId|', @stopUserId,       '~actionEventCancelOrderId|', @cancelOrderId);"
