{
    "AcknowledgeAdminId": "DECLARE @OrderId int = {{ActionEventOrderid}};   DECLARE @AdminId int = (SELECT MIN(id) FROM order_administrations WHERE patient_order_id = @OrderId AND acknowledge_user_id IS NULL)   IF @AdminId IS NULL BEGIN     DECLARE @date DATETIMEOFFSET = DATETIMEOFFSETFROMPARTS(       DATEPART(YEAR, getdate()),       DATEPART(MONTH, getdate()),       DATEPART(DAY, getdate()),       DATEPART(HOUR, getdate()) + 1,       0,0,0,(SELECT DATEPART(tzoffset, SYSDATETIMEOFFSET())) / 60,0,7)     DECLARE @MaxAdminTime DATETIMEOFFSET = (SELECT  MAX(administration_scheduled_datetime) FROM order_administrations WHERE patient_order_id = @OrderId)     IF @MaxAdminTime >= @date       SET @date = DATEADD(HOUR, 1, @MaxAdminTime);       WITH src AS (       SELECT @OrderId as patient_order_id, t.*       FROM ( VALUES         (1, 0, 0,  @date)       ) t (point_in_time, on_hold, missed_dose, scheduled)     )     INSERT  order_administrations         (patient_order_id, point_in_time, on_hold, missed_dose, administration_scheduled_datetime)     SELECT  patient_order_id,  point_in_time, on_hold, missed_dose, scheduled     FROM src;     SET @AdminId = SCOPE_IDENTITY()   END   SELECT AdminId = @AdminId;"
}

