    "GiveAdminId": "DECLARE @OrderId INT = {{ActionEventOrderid}};   DECLARE @AdminId INT = (SELECT MIN(oa.id) FROM order_administrations AS oa JOIN patient_orders AS o ON oa.patient_order_id = o.Id WHERE oa.patient_order_id = @OrderId AND oa.missed_dose = 0 AND ((oa.point_in_time = 0 AND oa.stop_datetime IS NULL) OR (oa.point_in_time = 1 AND oa.administration_datetime IS NULL)) AND o.order_status <> 'Pending')   DECLARE @Scheduled DATETIMEOFFSET = (SELECT administration_scheduled_datetime FROM order_administrations WHERE id = @AdminId)      IF (@AdminId IS NULL) BEGIN     DECLARE @date DATETIMEOFFSET = DATETIMEOFFSETFROMPARTS(       DATEPART(YEAR, getdate()),       DATEPART(MONTH, getdate()),       DATEPART(DAY, getdate()),       DATEPART(HOUR, getdate()),       0,0,0,(SELECT DATEPART(tzoffset, SYSDATETIMEOFFSET())) / 60,0,7)     DECLARE @MinAdminTime DATETIMEOFFSET = (SELECT  MIN(administration_scheduled_datetime) FROM order_administrations WHERE patient_order_id = @OrderId)        SET @date = DATEADD(HOUR, -1, @MinAdminTime);     WITH src AS (     SELECT @OrderId as patient_order_id, t.*     FROM ( VALUES       (1, 0, 0,  @date)     ) t (point_in_time, on_hold, missed_dose, scheduled))        INSERT  order_administrations         (patient_order_id, point_in_time, on_hold, missed_dose, administration_scheduled_datetime)     SELECT  patient_order_id, point_in_time, on_hold, missed_dose, scheduled     FROM src;     SET @AdminId = SCOPE_IDENTITY()   END      SELECT AdminId = @AdminId;"
