   is_active = 1     WHERE  id = @UserId   /**/     SET @sUserId = @UserId   END ELSE BEGIN     SET @sUserId = 'ERROR:  Couldn''t find Doctor in the site who was \"DOCTOR1\" for a patient in the site';   END   /**/   DECLARE @DocCount int = (     SELECT  COUNT(*) FROM dbo.users     WHERE  is_active = 1     AND    site_id = <<SiteId>>     AND    (type = 'D' or ordering_only_physician = 1)   );   /**/   SELECT CONCAT('ActiveDoctorCount|', @DocCount, '~PatientWithAttendingDoc|', @PatientIdWith, '~AttendingDoc|', @UserId, '~PatientWithNoAttendingDoc|', @PatientIdWithout, '~SiteIdWithNoDocs|', @NoDocsSiteIdWith);"
